-- # Lernfeld 5: Cyberphysische Systeme > ## Testgetriebene Entwicklung > - Tests > - Maßnahmen > - Testautomatisierung

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Testautomatisierung in der testgetriebenen Entwicklung (TDD) zwingend erforderlich, um den Entwicklungsprozess effizient zu gestalten?', 2, '[{"text": "Ja", "correct": true, "because": "Automatisierung ermöglicht schnelle Iterationen"}, {"text": "Nein", "correct": false, "because": "Manuell ineffizient"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Testautomatisierung in TDD ohne geeignete Frameworks sinnvoll umgesetzt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Frameworks bieten Struktur und Effizienz"}, {"text": "Ja", "correct": false, "because": "Ohne Frameworks aufwendig"}]'),
('00000000-0000-0000-0000-000000000000', 'Können automatisierte Tests in TDD die manuelle Fehleranalyse vollständig ersetzen?', 2, '[{"text": "Nein", "correct": true, "because": "Manchmal ist menschliche Analyse nötig"}, {"text": "Ja", "correct": false, "because": "Ergänzung bleibt wichtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss die Testautomatisierung in TDD alle Testarten wie Unit-, Integrations- und Systemtests abdecken?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus liegt oft auf Unit-Tests"}, {"text": "Ja", "correct": false, "because": "Flexibilität je nach Projekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine schlechte Testautomatisierung in TDD die Entwicklungszeit verlängern?', 2, '[{"text": "Ja", "correct": true, "because": "Unzuverlässige Tests verzögern"}, {"text": "Nein", "correct": false, "because": "Effizienz leidet bei Fehlern"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt die Testautomatisierung in TDD?', 2, '[{"text": "Schnelle und wiederholbare Testdurchführung", "correct": true, "because": "Kernvorteil der Automatisierung"}, {"text": "Erstellung detaillierter Berichte", "correct": false, "because": "Sekundär"}, {"text": "Vermeidung von Testfällen", "correct": false, "because": "Tests sind zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Framework ist für die Testautomatisierung in TDD mit Java am häufigsten im Einsatz?', 3, '[{"text": "JUnit", "correct": true, "because": "Standard für Java-Unit-Tests"}, {"text": "Selenium", "correct": false, "because": "UI-Tests, nicht TDD-Fokus"}, {"text": "Pytest", "correct": false, "because": "Für Python"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Testautomatisierung in TDD ist für die Fehlererkennung entscheidend?', 2, '[{"text": "Schnelle Rückmeldung", "correct": true, "because": "Fehler sofort sichtbar"}, {"text": "Hohe Komplexität", "correct": false, "because": "Eher hinderlich"}, {"text": "Manuelle Steuerung", "correct": false, "because": "Automatisierung zentral"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Art von Tests wird in TDD typischerweise automatisiert?', 2, '[{"text": "Unit-Tests", "correct": true, "because": "Kleine Einheiten im Fokus"}, {"text": "Systemtests", "correct": false, "because": "Spätere Phase"}, {"text": "Manuelle Tests", "correct": false, "because": "Nicht automatisiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptmerkmal der Testautomatisierung in TDD?', 2, '[{"text": "Kontinuierliche Ausführung", "correct": true, "because": "Sichert schnelle Iterationen"}, {"text": "Einmalige Durchführung", "correct": false, "because": "Nicht TDD-typisch"}, {"text": "Hohe Kosten", "correct": false, "because": "Effizienzsteigernd"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Testautomatisierung in TDD?', 4, '[{"text": "Schnelle Rückmeldung", "correct": true, "because": "Fehler sofort sichtbar"}, {"text": "Wiederholbarkeit", "correct": true, "because": "Tests jederzeit ausführbar"}, {"text": "Langsamere Entwicklung", "correct": false, "because": "Eher schneller"}, {"text": "Reduzierter manueller Aufwand", "correct": true, "because": "Automatisierung spart Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frameworks sind für die Testautomatisierung in TDD üblich?', 3, '[{"text": "JUnit", "correct": true, "because": "Java-Standard"}, {"text": "NUnit", "correct": true, "because": "Für .NET"}, {"text": "Photoshop", "correct": false, "because": "Kein Test-Tool"}, {"text": "Pytest", "correct": true, "because": "Python-Standard"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Effektivität der Testautomatisierung in TDD?', 3, '[{"text": "Qualität der Testfälle", "correct": true, "because": "Bestimmt Aussagekraft"}, {"text": "Testabdeckung", "correct": true, "because": "Sichert Vollständigkeit"}, {"text": "Teamgröße", "correct": false, "because": "Weniger relevant"}, {"text": "Wartbarkeit der Tests", "correct": true, "because": "Ermöglicht Anpassung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Herausforderungen gibt es bei der Testautomatisierung in TDD?', 4, '[{"text": "Hoher Initialaufwand", "correct": true, "because": "Tests erstellen kostet Zeit"}, {"text": "Wartung der Tests", "correct": true, "because": "Änderungen nötig"}, {"text": "Keine Fehlererkennung", "correct": false, "because": "Tests erkennen Fehler"}, {"text": "Komplexität bei Änderungen", "correct": true, "because": "Tests müssen angepasst werden"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien der Testautomatisierung sind in TDD entscheidend?', 3, '[{"text": "Schnelligkeit", "correct": true, "because": "Sofortige Rückmeldung"}, {"text": "Zuverlässigkeit", "correct": true, "because": "Konsistente Ergebnisse"}, {"text": "Manuelle Ausführung", "correct": false, "because": "Automatisierung zentral"}, {"text": "Wiederholbarkeit", "correct": true, "because": "Tests immer identisch"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Testautomatisierung in TDD ist optional. b) Automatisierte Tests beschleunigen den Entwicklungsprozess.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Automatisierung nötig, Beschleunigung real"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Testautomatisierung ersetzt manuelle Tests in TDD vollständig. b) Frameworks wie JUnit sind für TDD hilfreich.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Manuelle Tests ergänzen, Frameworks nützlich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Testautomatisierung in TDD erhöht die Testqualität immer. b) Schlecht gewartete Tests können die Entwicklung verzögern.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Qualität nicht garantiert, Wartung kritisch"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Testautomatisierung in TDD fokussiert sich auf Unit-Tests. b) Automatisierte Tests sind in TDD wartungsfrei.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unit-Tests primär, Wartung nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Testautomatisierung reduziert den manuellen Aufwand in TDD. b) TDD funktioniert ohne Testautomatisierung effizient.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Aufwand sinkt, Effizienz braucht Automatisierung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

